HOST = "https://" + spark.conf.get("spark.databricks.workspaceUrl")
TOKEN = dbutils.notebook.entry_point.getDbutils().notebook().getContext().apiToken().get()
def norm(s): return re.sub(r"[^a-z0-9]+"," ",(s or "").lower()).strip()
def call(req):
    r = requests.post(f"{HOST}/serving-endpoints/{ENDPOINT}/invocations",
                      headers={"Authorization":f"Bearer {TOKEN}","Content-Type":"application/json"},
                      json={"dataframe_records":[req]}, timeout=180)
    r.raise_for_status(); return r.json()["predictions"][0]

# COMMAND ----------
rows=[]; nname=0; ntype=0; ntop=0; miss=[]; nemb=0
for t in TESTS:
    exp=t["top"]
    try: pred=call(t["request"])
    except Exception as e:
        rows.append((t["q"],t["query"],"ERROR",str(e)[:60])); continue
    res=pred.get("results",[]) or []
    g0=res[0] if res else None
    if exp is None:
        v="OK-EMPTY" if not g0 else "GOT-RESULT"; rows.append((t["q"],t["query"],v,f"got {(g0 or {}).get('name')}")); continue
    if not g0:
        rows.append((t["q"],t["query"],"GOT-EMPTY",f"exp {exp['name']} (thematic? check Qwen embed)")); miss.append(t["q"]); continue
    ntop+=1
    name_ok = norm(g0.get("name"))==norm(exp["name"])
    type_ok = (g0.get("match_type")==exp["match"])
    nname += name_ok; ntype += type_ok
    v = "TOP-MATCH" if name_ok else "DIFF"
    if not name_ok: miss.append(t["q"])
    tag = " (demoted)" if exp.get("demoted") else ""
    detail=f"[{t['rating']}]{tag} exp {str(exp['name'])[:24]}({exp['match']}) | got {str(g0.get('name'))[:24]}({g0.get('match_type')},{g0.get('score')})"
    rows.append((t["q"],t["query"],v,detail))

print(f"{'Q':>3} {'verdict':11} {'query':22} detail")
for q,qu,v,d in rows: print(f"{q:>3} {v:11} {str(qu)[:22]:22} {d}")
print("\n"+"="*70)
print(f"TOP-1 name match : {nname}/{ntop}  ({round(100*nname/max(ntop,1))}%)")
print(f"match_type match : {ntype}/{ntop}")
print(f"GOT-EMPTY (mostly thematic -> Qwen embed) + DIFF: {len(miss)} -> Q{miss}")
print("NOTE: GOT-EMPTY on thematic queries = the Qwen query-embed endpoint is unreachable. Name/prefix/fuzzy")
print("      queries do NOT need embed. Check debug.route.thematic_embed on a thematic query with debug=true.")
